// 1) 定义接口
public interface PayChannel { void pay(long cents); }

// 2) 实现类
public class WechatPay implements PayChannel {
    public void pay(long cents) { System.out.println("wechat pay " + cents); }
}

// 3) 资源文件：META-INF/services/com.example.PayChannel
//    内容：com.example.WechatPay

// 4) 运行时加载
import java.util.ServiceLoader;
public class SpiDemo {
    public static void main(String[] args) {
        for (PayChannel ch : ServiceLoader.load(PayChannel.class)) {
            ch.pay(100);   // 加载并实例化所有已注册实现
        }
    }
}
